import { readFileSync } from "node:fs";

import type { APIRequestContext } from "@playwright/test";

import { expect, sample, test, uniqueName } from "../../fixtures";

interface ReviewQueueItem {
  vendor_id: string;
  lowest_confidence: number;
}

async function createInReviewVendor(
  member: APIRequestContext,
  name: string,
  insuranceFile: string,
): Promise<string> {
  const created = await member.post("/api/vendors", {
    data: { name, category: "services", contact_email: "ops@harborline.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const documents: [string, string][] = [
    ["w9", "w9.txt"],
    ["insurance_certificate", insuranceFile],
    ["contract", "contract.txt"],
  ];
  for (const [kind, file] of documents) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind,
        file: { name: file, mimeType: "text/plain", buffer: readFileSync(sample(file)) },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  // Extraction runs in the background; wait until all three documents are extracted.
  await expect
    .poll(async () => {
      const res = await member.get(`/api/vendors/${vendor.id}/documents`);
      const docs = (await res.json()) as { status: string }[];
      return docs.filter((d) => d.status === "extracted").length;
    }, { timeout: 15_000 })
    .toBe(3);

  const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submitted.status(), await submitted.text()).toBe(200);
  return vendor.id;
}

async function fetchQueue(reviewer: APIRequestContext): Promise<ReviewQueueItem[]> {
  const res = await reviewer.get("/api/review-queue");
  expect(res.status(), await res.text()).toBe(200);
  return (await res.json()) as ReviewQueueItem[];
}

test("the review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");

  // Arrange
  const unparsedId = await createInReviewVendor(
    member,
    uniqueName("Unparsed Co"),
    "insurance_certificate_unparseable.txt",
  );
  const clearId = await createInReviewVendor(
    member,
    uniqueName("Clear Co"),
    "insurance_certificate.txt",
  );
  await expect
    .poll(async () => (await fetchQueue(reviewer)).map((i) => i.vendor_id))
    .toEqual(expect.arrayContaining([unparsedId, clearId]));

  // Act
  const queue = await fetchQueue(reviewer);

  // Assert
  const unparsedIndex = queue.findIndex((i) => i.vendor_id === unparsedId);
  const clearIndex = queue.findIndex((i) => i.vendor_id === clearId);
  expect(unparsedIndex, "unparsed vendor is in the queue").toBeGreaterThanOrEqual(0);
  expect(clearIndex, "clear vendor is in the queue").toBeGreaterThanOrEqual(0);
  expect(unparsedIndex, "unparsed vendor is listed before the other").toBeLessThan(clearIndex);
  expect(queue.map((i) => i.lowest_confidence), await JSON.stringify(queue)).toEqual(
    [...queue.map((i) => i.lowest_confidence)].sort((a, b) => a - b),
  );
});
